import { readFileSync, writeFileSync } from 'fs';

const FILE = 'js/parrafos-textos/parrafos-texto-ingles.json';
const existing = JSON.parse(readFileSync(FILE, 'utf8'));

const LOGO = "<img src='imagenes/imagenes-aplicación/logo_alargado_3.png' alt='València be Guides' style='height:1.4em;vertical-align:baseline;position:relative;bottom:-0.2em;'>";

const batch = {
"344": `<p>Above the main entrance, beneath a semicircular arch, allegorical figures represent the five continents.</p>\n<p>What does the central figure hold? A Crown, a Sword or perhaps a Torch?</p>`,
"345": `<p>Facing the post office building, turn to your left, as indicated on your map, towards Calle de las Barcas — the second street on your right.</p>\n<p>${LOGO} recommends arriving at the next point of interest on foot; please respect the highway code, which in this case gives pedestrians right of way.</p>\n<p>Do not pause this audio guide and make your way to the indicated point, thank you.</p>\n<p>Come on, it is only a few metres! Remember: look at the building, turn left and take the second street on your right.</p>`,
"346": `<p>If you are visiting during opening hours, ${LOGO} encourages you to stop and find a good spot.</p>\n<p>It is the perfect place to take a break and capture stunning photos of the city's architectural treasures, and enjoy a typical drink: Agua de Valencia, an alcoholic cocktail made with vodka, cava and fresh orange juice. Or even better... you can also taste an Orxata, our vegan tiger nut juice, always accompanied by its beloved Fartons — a bar-shaped sponge cake you must dip until it soaks through, then eat. That is how the people of Valencia enjoy this refreshing cultural drink.</p>\n<p>Remember, there is no rush; do whatever you fancy and don't put pressure on yourself — this is supposed to be a fun excursion! You can return to your Adventure whenever you feel the moment is right, simply by pressing play.</p>`,
"347": `<p>Calle de las Barcas takes its name from a succession of workshops that once lined this street, where small boats were built and then transported to the fishermen's quarter.</p>\n<p>In its time, it was filled with coffee houses and taverns, where prostitution and gambling alarmed the local population.</p>\n<p>With the expansion of the <strong>Plaza del Ayuntamiento</strong> in 1891, landmark buildings were erected in the area — the ones you are about to see.</p>`,
"348": `<p>Continue to the end of the street, where you will see the former headquarters of the <strong>Banco de Valencia</strong>.</p>`,
"349": `<p>Despite its classical composition on a chamfered corner, the building includes typical Valencian elements such as its ceramic tiles with floral motifs on the attic storey and its slender bay windows facing the side streets.</p>\n<p>The base of the building, two storeys high, is defined by a combination of two-colour marble and a series of classical columns supporting the railings, with gilded elements offering the protective image sought by the Bank.</p>\n<p>The former headquarters of the <strong>Banco de Valencia</strong> is an essential architectural treasure on this adventure.</p>`,
"350": `<p>How many storeys does the building have?</p>`,
"351": `<p>Admiring this façade, continue your adventure as indicated on your map, down the street opening to your left, towards the next point of interest.</p>\n<p>Do not pause this audio guide and make your way to the recommended location.</p>\n<p>Please respect the highway code. Thank you.</p>`,
"352": `<p>Along the way, amid the modernity of the buildings, one of the ten founding parishes of the city stands out.</p>\n<p>As a curiosity, we note that the Church of San Juan de la Cruz was left in a deplorable state during the Spanish Civil War, which took place between 1936 and 1939.</p>\n<p>The temple was ransacked, and its works of art and altarpiece were destroyed.</p>\n<p>The occupants also used the space as a heavy ballistics warehouse.</p>`,
"353": `<p>Once you reach the church, please turn your attention, if you would be so kind, to the Solomonic columns of the lintel doorway, as we will provide more information about these throughout this Adventure — this is a good place to examine them in detail.</p>\n<p>Pause this audio guide if you wish.</p>`,
"354": `<p>Have you reached the point of interest yet? Not yet? We hope this brief history makes your journey more enjoyable.</p>\n<p>It is worth noting that in 1496, the Marquis of Rabassa de Perellós acquired the title of Baron of Dos Aguas for a considerable sum, and the Barony was elevated to a Marquisate in 1699.</p>\n<p>For three centuries, the Rabassa de Perellós family held high positions in political governance, while accumulating dowries and inheritances through marriage.</p>\n<p>This building has undergone lavish modifications over the course of its history, as a display of power and lineage.</p>\n<p>Today it houses the National Ceramics Museum.</p>\n<p>Please stand in front of the main entrance, which is around the corner.</p>\n<p>Pause this audio guide if you wish.</p>`,
"355": `<p>Admire the Cathedral from top to bottom and you will see three superimposed galleries formed by openings with semicircular arches.</p>\n<p>Built in 1566 in a Renaissance style, this is a grandstand-viewpoint known as the "Obra Nova", intended for watching processions and public events from the Cathedral itself.</p>`,
"356": `<p>The composition of this doorway dates from the 18th century.</p>\n<p>On it we see an image of Our Lady of the Rosary, from whom two streams of water descend alongside two atlantes representing the two most abundant rivers of Valencia — the Turia and the Júcar — in clear reference to the name of the marquisate.</p>\n<p>At the feet of the Virgin we can see two kneeling matrons: one holding a cornucopia overflowing with fruit (Allegory of agriculture and prosperity), and another with a vessel at her feet filled with coins (Allegory of justice and magnanimity).</p>\n<p>It was in the 19th century that the heir of the marquises undertook a second spectacular renovation, based primarily on the interior decoration.</p>\n<p>He also modified the exterior of the Palace, combining the Rococo style with Chinese and French-inspired motifs of the era, such as: the use of railings on windows and balconies, and the enormous armour that protrudes from the façade, giving it its current appearance.</p>`,
"357": `<p>Inside, you can still see 18th-century carriages as well as the 19th-century salons, while the second floor houses the ceramics museum.</p>\n<p>If you are visiting during opening hours, ${LOGO} recommends pausing and visiting this historic complex at your own pace. You may resume your adventure whenever you feel ready.</p>`,
"358": `<p>Stand with the main façade of the Palace on your left and continue to the end of the street.</p>\n<p>You will arrive once again at the famous Calle San Vicente Mártir.</p>\n<p>The layout of this street has remained unchanged since the fourth century AD.</p>\n<p>Calle San Vicente Mártir is today one of the longest thoroughfares in the city.</p>\n<p>On this street dedicated to Valencia's patron saint, turn left and continue your treasure hunt to the end of the street.</p>`,
"359": `<p>Take the <strong>Plaza del Ayuntamiento</strong> as your reference — number <mark>27</mark> on your map — but this time turn right.</p>`,
"360": `<p>Just 150 metres away, in the next square, monuments from different eras come together in the present, forming part of our daily lives.</p>\n<p>Your treasure hunt begins with the monumental building on the left.</p>`,
"361": `<p>Imagine you are in a bygone era!</p>`,
"362": `<p>This monument dedicated to commerce was built on the site of an open-air market that had existed since 1839, already known at that time as the <strong>Mercado Central</strong>, which in turn stood on the ancient Muslim market or souk located outside its walls.</p>\n<p>The <strong>Mercado Central</strong> we can see today, inaugurated in 1928, occupies a Modernist building in which ceramics, iron, stone, and large stained-glass windows and domes adorn both the interior and exterior.</p>\n<p>Looking at the building as a whole, one of its domes features a parrot-shaped weather vane.</p>`,
"363": `<p>Legend has it that this refers to the gossip and chatter that have always been a staple of markets, and so it is nicknamed "la <strong>Cotorra del Mercado</strong>" — the Market Parrot.</p>`,
"364": `<p>As a modern-style building, the Market blends perfectly with the other two important monuments in the square: the Church of San Juan del Mercado and the <strong>Lonja</strong>, both iconic landmarks of 15th-century Valencia.</p>\n<p>Find the stained-glass window with the colours of the Valencian Senyera on the building's façade. Can you tell what shape it is? Rectangular, Round or Triangular?</p>`,
"365": `<p>Known as the Church of San Juan del Mercado, this is another clear example of a parish church built over an Arab mosque.</p>\n<p>A serious fire in 1300 AD forced an almost complete rebuilding from the rubble.</p>\n<p>Centuries later, another fire caused a further reconstruction, giving it its current Gothic appearance while retaining part of its original Baroque elements.</p>\n<p>In 1936, during the Civil War, a third fire devastated the church, and the damage was repaired in the first quarter of the 21st century.</p>`,
"366": `<p>Among its exterior ornamentation, a large stone altarpiece of Our Lady of the Rosary stands out.</p>\n<p>What does the Virgin hold in her hand? A rosary? A child? Perhaps a crown?</p>`,
"367": `<p>What does the angel give to the child? Is it a dove? Perhaps an orb? Or maybe food?</p>`,
"368": `<p>A lesser-known name for this temple is the "Church of the Rogues", because it was historically the place chosen by children who, due to the circumstances of the time, engaged in mischief and committed petty thefts from market passers-by. Imagine medieval pickpockets — is this perhaps a profession with a very long history?</p>`,
"369": `<p>Admiring this building, the next point of interest is directly behind you — simply turn around.</p>`,
"370": `<p>The <strong>Lonja de la Seda</strong> is the monument of Valencia's Golden Age.</p>\n<p>In its day, the <strong>Lonja de Valencia</strong> was a 15th-century Wall Street.</p>\n<p>The monument was built between 1482 and 1497 and was declared a World Heritage Site in 1996.</p>\n<p>This financial building began as the <strong>Lonja de la Seda</strong>, as the famous Silk Road — a trade route stretching from Africa to China or India — passed through Valencia.</p>\n<p>It is worth noting that other goods such as spices, porcelain, iron and tea were also traded along the Silk Road, but beyond its commercial purpose, it was also a space for the exchange of ideas and knowledge.</p>\n<p>The monument's footprint follows a rectangular plot and covers more than 2,000 square metres.</p>\n<p>Its south face looks towards the Plaza del Mercado, where you are standing right now.</p>\n<p>The east façade faces Calle de Pere Compte, the master builder of the monument.</p>\n<p>The west face overlooks Calle de los Cordellats, where you can catch a glimpse of the Orange Tree Courtyard.</p>`,
"371": `<p>And finally, the north face overlooks Calle de la <strong>Lonja</strong> — your next destination on this adventure.</p>`,
"372": `<p>From your position, four sections can be distinguished: to the right, the Sala de Contratación or Columned Hall, where transactions took place.</p>`,
"373": `<p>In the centre, a three-storey Tower used as a chapel on the ground floor and as a prison on the two upper floors, where dishonest thieves, merchants and traders were held until the authorities came to deal with them.</p>`,
"374": `<p>To your left, the Sala del Consulado del Mar (1498–1548), built subsequently to handle maritime and commercial matters — this was the first commercial tribunal established in Spain.</p>`,
"375": `<p>From this point, we invite you to take a journey back in time through the sculptures of the <strong>Lonja de Valencia</strong>.</p>\n<p>This activity involves observing the expressiveness and originality of its porticoes and gargoyles, carved by stonemasons in the 15th century:</p>`,
"376": `<p>The image of angels holding a shield, on one of the outer corners of the monument — a heraldic and celestial sign far removed from the other figures — is probably the most innocent thing you will find on the walls of the <strong>Lonja de la Seda</strong>.</p>`,
"377": `<p>Stand before what was the main entrance portico, known as the Puerta de los Pecados (Door of Sins), which is to the right of the façade in front of you now.</p>\n<p>It demands your special attention and the ability to read "between the lines" its numerous messages about the darkness of sin and evil.</p>\n<p>On this doorway it is easy to find hundreds of demonic figures: monsters, creatures consumed by evil, spells, humans terrified by lust and the capital sins, evidence of eroticism with a distinctly perverse and lascivious accent — scenes that lead us into the obscurantism that predominates in this civic building.</p>`,
"378": `<p>In the 15th century, many merchants, as well as the majority of lower-class citizens, could not read or write; so they interpreted the figures as a guide to preventing sin.</p>\n<p>One must not forget that in the capital of the Turia stood one of the largest brothels in all of Europe. And so, as a sign of protection, the Virgin and Child crown the doorway.</p>`,
"379": `<p>If you look closely, you will be able to find:</p>\n<p>The boatman rowing against the current — a man with a sad face steering a small wooden boat, escaping against the tide from a monster.</p>`,
"380": `<p>Have you spotted him? So, is our man fleeing from that monstrous creature called temptation?</p>`,
"381": `<p>A dead tree: a symbol of sin, it stands between the two doors and serves as a central column.</p>\n<p>Look at the top of the tree — four naked men are flogging one another.</p>\n<p>Have you spotted them all? Congratulations!</p>`,
"382": `<p>The <strong>Fuente del Negrito</strong> was inaugurated in 1850.</p>\n<p>At the time, public fountains were the recipients of the city's newly arrived drinking water supply.</p>\n<p>Running water had not yet reached most homes, and people had to collect it from public fountains for personal use.</p>`,
"383": `<p>Now pay attention to some of its gargoyles — step back a little to see them high up on the building:</p>`,
"384": `<p>To the right, an angel displaying its penis and about to insert it into a vase it holds in its other hand. Somewhat unusual and strange, wouldn't you say?</p>`,
"385": `<p>In the centre, the bearded man and the lion:</p>\n<p>An original and contradictory scene in which the gentle one is, surprisingly, the lion and not the bearded old man.</p>\n<p>In fact, the evidence here points to the story of Samson defeating a lion — a parallel to the life of Jesus battling the Devil.</p>`,
"386": `<p>Here is a bonus challenge!</p>\n<p>Find the fornicator of the <strong>Lonja</strong>!</p>\n<p>In one of its windows, you will find a man fornicating with the wall of the most important civic building of the era.</p>\n<p>His head cannot be seen, but his genitals very certainly can.</p>\n<p>That, or he is answering a call of nature.</p>`,
"387": `<p>Did you find him? Bravo! That was a tough one!</p>`,
"388": `<p>Study your map carefully. From your position, it takes you around the <strong>Lonja</strong> and around the corner.</p>\n<p>The Orange Tree Courtyard gives access to a stone staircase leading to the main floor of the Consulate Pavilion — a spacious hall where the commercial judges once held their sessions — and links the three sections of the building.</p>`,
"389": `<p>Is it a good time to begin your adventure? Yes, No</p>`,
"390": `<p>Look at the gargoyle on the tower.</p>\n<p>To the left, there is a completely naked woman touching her genitals with both hands.</p>`,
"391": `<p>A figure devoid of sensuality or eroticism, recreating the act of masturbation (sinful according to the morality of the era).</p>\n<p>We return once more to lust, the overwhelmingly dominant theme in the sculptures decorating the building.</p>\n<p>It is probably the most recognised, famous and surprising figure at first glance in the <strong>Lonja de la Seda</strong> of Valencia.</p>\n<p>Since the 15th century, the <strong>Lonja</strong> and its virtuous figures laden with obscenity have looked out over the streets of this city of Valencia.</p>\n<p>Statues that come alive on the walls of a building that is no longer in the 15th century but in the 21st, whose passers-by stop and ask themselves: what are they trying to tell us?</p>`,
"392": `<p>Further along, following the building, you will find the entrance to the monument.</p>\n<p>If you are visiting during opening hours, ${LOGO} recommends pausing and going inside this monument to learn more about the history of the city and its customs.</p>\n<p>You may resume your adventure whenever you feel ready.</p>`,
"393": `<p>Stand with the entrance to the <strong>Lonja</strong> behind you and make your way to your right, towards the old doorway that gives access to the building — the last one you have yet to see.</p>\n<p>Once there, observe the entrance carefully while you listen to the following story.</p>`,
"394": `<p>There are around 10,000 Saints officially canonised by the Catholic Church.</p>\n<p>It is a long process that can take many years due to its complexity.</p>\n<p>The candidate must be a servant of God; for this, their life must be exemplary and virtuous.</p>\n<p>A specialised institution collects the main aspects of their life and compiles them into virtues and written accounts.</p>\n<p>If their deeds were heroic, the Holy Father declares them a "Venerable Person".</p>\n<p>After performing their first miracle, that person will be beatified.</p>\n<p>To become a Saint, the candidate must have performed at least three miracles demonstrating their intercession.</p>`,
"395": `<p>If you are visiting during opening hours, ${LOGO} recommends pausing and visiting this monument at your own pace to learn a little more about the history of the city.</p>`,
"396": `<p>If you are visiting during opening hours, ${LOGO} recommends pausing and going inside this space to learn more about the history of the city.</p>\n<p>You may resume your adventure whenever you feel ready, simply press the corresponding button and continue <i>in search of the treasure</i>.</p>\n<p>Your adventure continues from this very point.</p>`,
"397": `<p>From your new vantage point, with the entrance to the monument directly in front of you, turn to your left and you will see an open square.</p>\n<p>Move closer, if you would be so kind, to the open square on your left.</p>`,
"398": `<p>This is the original location of the <strong>Lonja de Valencia</strong>.</p>\n<p>Records of its existence date back to 1344.</p>\n<p>In the old <strong>Lonja</strong>, oil and spices were traded, and it remained standing until the 19th century.</p>\n<p>However, due to growing immigration, the merchants of the 15th century were obliged to build a larger building capable of accommodating the unexpected surge in commercial activity that the city experienced during its Golden Age.</p>`,
"399": `<p>You are standing, at this very moment, in the place where, according to tradition, one of Valencia's most celebrated miracles took place.</p>`,
"400": `<p>In 1358, Vicente Ferrer was preaching at the gates of the old <strong>Lonja de Valencia</strong>.</p>\n<p>The sermon that Vicente Ferrer was delivering that day reminded good people of the need to help those who were suffering and dying from poverty and starvation, and of the necessity of their charity.</p>\n \n<p>The theologian of the <strong>Catedral de Valencia</strong> at the time, to demonstrate this, took out a handkerchief and threw it into the air, telling the crowd to follow it.</p>\n<p>Wherever the handkerchief came to rest, they would find people truly in need of their charity.</p>`,
"401": `<p>The handkerchief flew to a specific point and the crowd was able to see that in that house there was a family on the verge of death in the most absolute misery, and the compassionate people came to the family's aid.</p>`,
"402": `<p>In this way, the famous miracle of the Mocaoret was interpreted — which in Valencian means "little handkerchief" — a miracle attributed to the future Saint of the Valencian Community.</p>`,
"403": `<p>In this adventure you will follow part of the flight path of that handkerchief, which will lead you to the famous <strong>Plaza Redonda</strong>.</p>\n<p>Open your map and observe: it indicates leaving this square on your left and entering the street directly in front of you.</p>\n<p>Pay attention to your map — your next objective is the famous <strong>Plaza Redonda</strong>, located on the fourth street to the left and then the first on the right.</p>\n<p>Shall I repeat that? Of course, with pleasure!</p>\n<p>Fourth street on the left and then the first on the right.</p>`,
"404": `<p>During Fallas, everything is celebration: the roar of the mascletà, the casales, the street parades, the flower offering and the bands of music make their way through the more than 700 Fallas monuments.</p>`,
"405": `<p>The former meat and fish market, the <strong>Plaza Redonda</strong>, is the oculus of Valencia — an eye gazing up at the sky.</p>\n<p>It corresponds today to number <mark>36</mark> on your map.</p>\n<p>Remember to press pause, then go to or observe the indicated point, and press the continue button again once you are at the suggested location. Thank you.</p>`,
"406": `<p>Since its renovation in 2012, the <strong>Plaza Redonda</strong> has the appearance of a modern square without losing its historic charm.</p>\n<p>In this square, a great Valencian tradition remains very much alive.</p>\n<p>Even today, bobbin lace workshops can be seen — a textile technique that consists of interlacing threads over a pattern to create embroidery.</p>\n<p>A technique requiring skills such as attention, concentration, dexterity and, above all, fine motor control in the fingers.</p>\n<p>Inside the square, specialist shops selling handmade lace and embroidery can still be found. You will also enjoy magnificent souvenirs, all of them in Valencian style, and bars where you can taste our typical tapas.</p>\n<p>${LOGO} recommends pausing and visiting this square at your own pace.</p>`,
"407": `<p>Once you decide to continue your adventure, we challenge you to find the correct exit.</p>\n<p>Do you dare?</p>\n<p>One of the multiple possible exits leads you to a square with several points of interest in your treasure hunt.</p>\n<p>Your next objective is the Plaza de Santa Catalina, indicated on your map as number <mark>37</mark>.</p>`,
"408": `<p>We have a curiosity in store for you! Valencia is full of architectural and historical treasures that we reveal in each of our Adventures.</p>`,
"409": `<p>From the centre of the square, one of the narrowest buildings in Europe can be seen — can you spot it?</p>\n<p>Just imagine: the first floor a dining room, the second the kitchen, and so on.</p>`,
"410": `<p>How wide is the entrance?</p>`,
"411": `<p>This treasure hunt invites you to approach Santa Catalina; from the centre of the square you can take in the church in its entirety.</p>\n<p>As you can see, the church is partially enclosed by the surrounding houses and looks quite unassuming from the outside.</p>`,
"412": `<p>The origins of the <strong>Iglesia de Santa Catalina</strong> Màrtir date back to the reconquest of Valencia itself in 1238.</p>\n<p>Following the reconquest and subsequent change of religion in the city, James I sought to reorganise the urban space.</p>\n<p>To this end, he granted ownership of all Muslim mosques and cemeteries to the archbishopric, which in turn Christianised these temples by renaming them as parishes dedicated to saints of the new religion that would be established in these lands.</p>\n<p>In May 1239, just one year after the reconquest, the Parish of Santa Catalina became one of the ten founding parishes of the city.</p>\n<p>It should also be noted that the seizure of the mosques was not merely an instrument of Christianisation and ecclesiastical control over neighbourhood life, but also an instrument of administrative and political organisation; in fact, the town council was formed, in part, by the various parishes of the city.</p>`,
"413": `<p>Over the years, parish churches of Christian plan began to be built on the sites of the former mosques.</p>\n<p>The <strong>Iglesia de Santa Catalina</strong> was completed in 1371. However, in 1740, it underwent a renovation lasting 15 years, resulting in an almost complete renewal of the temple.</p>`,
"414": `<p>Urban legend has it that the contract between the architect and the church did not specify the construction of a staircase to access the upper levels of the tower, so the architect built the tower without access to its upper floors.</p>\n<p>Today, the tower can be accessed via a spiral staircase that allows entry to the balustrade.</p>\n<p>If you are visiting during opening hours, ${LOGO} recommends pausing and walking through the interior of this temple, as well as visiting its tower.</p>\n<p>Your adventure continues from this very point.</p>`,
"415": `<p>The route ahead requires your special attention, as it will reveal a hidden story on your treasure map. Will you be able to find it? A gigantic shell carved in stone, to your right and attached to the retaining wall within the garden itself, reveals part of the city's tragic history.</p>`,
"416": `<p>Focus your attention on the façade directly in front of you. Three blind arches open within it.</p>\n<p>Two of them are smooth; the third was left unfinished.</p>\n<p>What can be seen in that arch? Can you see a face? Is there perhaps a torso? And a gargoyle?</p>`,
"417": `<p>Until 1520, this façade housed the office responsible for market surveillance and public hygiene, as well as the control of the city's weights and measures, given that the city's butchers and fishmongers were just a few metres away.</p>\n<p>In earlier times, this was the commercial and mercantile district where most of the city's most important guilds were based.</p>`,
"418": `<p>Your treasure map takes you around the church in the direction of the tower.</p>\n<p>On your map it corresponds to number <mark>38</mark>.</p>\n<p>Do not pause this audio guide and make your way to the indicated point.</p>`,
"419": `<p>Position yourself, if you would be so kind, at a point from which you can see the tower in its entirety, and take your time to photograph this magnificent monument while getting to know it more deeply.</p>\n<p>Remember to press pause, then observe the indicated point, and press the continue button again once you are at the suggested location.</p>`,
"420": `<p>Santa Catalina Màrtir is a visitable tower considered one of the most original Baroque towers in Spanish architecture.</p>\n<p>The first stone of this bell tower was laid in 1688 and it was finally completed in 1705 in its current Baroque style.</p>\n<p>As you can appreciate, the tower has a hexagonal plan.</p>\n<p>It rises in four storeys, to which the bell chamber and a small temple structure must be added — a construction of columns and a roof similar to a small temple.</p>\n<p>On each of its storeys, richly decorated windows in the Baroque style open to allow light into the staircase.</p>\n<p>The bell chamber displays the greatest decorative richness. Admire the Solomonic columns bound at each of its edges.</p>\n<p>These columns take their name from the belief of the time that they resembled the columns of Solomon's Temple.</p>\n<p>Completing the bell chamber are the semicircular arches that open on each face of the tower.</p>\n<p>As a final note, regarding the six bells installed in the bell tower since 1729, they were known as "the Lutherans" because they came from London, a non-Catholic country.</p>\n<p>Sadly, those bells came to various different ends.</p>`,
"421": `<p>The tower is crowned by a two-storey structure supported by a set of volutes — so named for their snail or spiral shape — which support the central body.</p>\n<p>The Solomonic bound columns are repeated here again — can you see them?</p>\n<p>The structure is covered by a dome with fish-scale stone tiles.</p>\n \n<p>Above the dome, a globe representing the Earth and a weather vane allow Santa Catalina to exceed 56 metres in height.</p>`,
"422": `<p>What colour are the dome tiles?</p>`,
"423": `<p>What is at the very top of the tower? Could it be a cross? Perhaps the sun? Maybe there is a dove?</p>`,
"424": `<p>Do not pause this audio guide. Your treasure map indicates crossing the square and finding the exit on the opposite side.</p>\n<p>From 2012 onwards, this square and the adjoining one to your left were transformed from a succession of ruins into two renovated small squares hosting spaces for markets.</p>\n<p>In <strong>Tapinería</strong>, as the group of squares is known, the philosophy of the ephemeral prevails — the goods and styles change every fortnight.</p>`,
"425": `<p>Tradition has it that the tower of Santa Catalina is the sweetheart of the <strong>Miguelete</strong>: "Two lovers who gaze at each other eternally, but whose shyness prevents them from drawing closer."</p>`,
"426": `<p>The <strong>Miguelete</strong> is a visitable monument in the Valencian Gothic style that takes its name from its main bell, which has been striking the hours from 1539 to the present day.</p>\n<p>Approach the monument, as indicated on your map.</p>`,
"427": `<p>The iconic <strong>Miguelete</strong> is made up of four sections of equal height.</p>\n<p>This important point on your Adventure serves as both a bell tower and a viewpoint, as it is the tallest building in the historic city.</p>\n<p>Can you determine its shape? Hexagonal, Octagonal or Quadrangular?</p>`,
"428": `<p>In its origins, the <strong>Torre del Miguelete</strong> was designed to stand apart from the Cathedral, but a 15th-century renovation caused it to be joined to the tower.</p>\n<p>How many windows can you see?</p>`,
"429": `<p>Focus your attention slightly to your right.</p>`,
"430": `<p>Subsequently to the construction of the <strong>Miguelete</strong>, the Baroque doorway of the cathedral was added. Today it is its main entrance.</p>\n<p>Commonly known as the "<strong>Puerta de los Hierros</strong>", it connects the temple with the <strong>Torre del Miguelete</strong> and frames the space with the metal grille that gives the doorway its name.</p>\n<p>This grand design was conceived to create the optical illusion of greater space in a relatively small area, replacing the traditional straight lines with a concave-convex curvature.</p>\n<p>Standout features include the columns and the oval rose window that illuminates the Cathedral, and above it, a high-relief depicting the Assumption of the Virgin.</p>\n<p>The attic of the doorway is crowned by a bas-relief with the symbol of the Holy Spirit.</p>\n<p>This doorway, completed in 1741, is the most modern entrance to the Cathedral.</p>\n<p>It is worth noting that it was built thanks to a donation left by a female citizen in her will.</p>`,
"431": `<p>What can be seen at over 35 metres height at the top of the Baroque doorway? Is it a sphere? A cross? Perhaps a bat? Or a horse?</p>`,
"432": `<p>In our century, the <strong>Puerta de los Hierros</strong> is divided in two: the left side provides access for worshippers and also leads to the ascent of the <strong>Miguelete</strong>.</p>\n<p>From here, the High Altar can also be glimpsed — a Renaissance altarpiece adorned with resplendent Gothic decoration.</p>\n<p>The right side offers the Cathedral's museum section. From here, access is also provided to the numerous chapels, including that of San Vicente Mártir, where the Saint's incorrupt arm is on display.</p>\n<p>If you are visiting during opening hours, ${LOGO} recommends pausing and visiting this monument at your own pace.</p>\n<p>After climbing its 207 steps, the <strong>Miguelete</strong> offers 360° aerial views of the entire city.</p>\n<p>The panorama from the <strong>Miguelete</strong> at 51 metres height allows you to see the whole city, from its vast gardens to the <strong>City of Arts and Sciences</strong>.</p>\n<p>This is a perfect spot for panoramic photographs of the city.</p>\n<p>You may resume your adventure whenever you feel ready, simply press the corresponding button and continue <i>in search of the treasure</i>.</p>\n<p>Your adventure continues from this very point.</p>`,
"433": `<p>Leave the <strong>Plaza de la Virgen</strong> on your left, continue to the end of the street and then turn right.</p>\n<p>You will find yourself in the <strong>Calle de los Serranos</strong>, which separates and defines, on the right, the "La Seu" neighbourhood or <strong>Cathedral Quarter</strong>, and on the left, the "El Carmen" neighbourhood.</p>`,
"434": `<p>The construction of the Cathedral took 500 years to complete, and during this extended period architectural styles evolved; as a result, several architectural styles come together in the <strong>Catedral de Valencia</strong>.</p>\n<p>Its north face is its oldest façade.</p>`,
"435": `<p>These styles can be seen very clearly in its three doorways: the Baroque one — the main entrance — which is directly in front of you.</p>\n<p>On the west side is the Gothic portal you will see during this Adventure, and the east side with its Romanesque entrance, which will be your next objective.</p>`,
"436": `<p>Particularly notable is the so-called "La Nit del Foc" (Night of Fire), which takes place on the night of 18–19 March, drawing over a million people to watch it, as it stands out for being the longest and most spectacular of all.</p>`,
"437": `<p>Move a little closer to the Cathedral doorway.</p>\n<p>The Romanesque doorway of the cathedral, also known as the Puerta del Palau, is a Romanesque doorway in a Gothic-style temple.</p>\n<p>At its base, 12 scenes are carved on each side, depicting historical passages from the Bible, from Genesis and Exodus.</p>\n<p>Known as the dry doorway, it is composed of six semicircular arches with geometric motifs; on it can be seen figures of seraphim, angels, small arches and delicate, highly elaborate foliage.</p>\n<p>Above the arcade are the heads of seven couples who, according to tradition, represent seven married couples from Lleida who arrived bringing with them three hundred maidens to be wed to the new settlers and thus repopulate Valencia after the war.</p>`,
"438": `<p>How many arches make up the doorway?</p>`,
"439": `<p>On the right-hand side of the doorway, at knee height, you can see some longitudinal marks resembling scratches.</p>\n<p>In this very square where you are standing, there used to be the platform on which the executioner carried out sentences.</p>\n<p>Ancient accounts tell that these are marks made by the executioner repeatedly sharpening his axe in the same spot, as the dreaded place of execution was just a few metres from the doorway — an event that was, of course, public! The people were permitted to attend and witness justice being served.</p>`,
"440": `<p>Do not pause this audio guide and continue along the wall of the temple.</p>`,
"441": `<p>Have you noticed that the Cathedral wall is rounded? The <strong>Catedral de Valencia</strong> was built on the ancient Visigothic See, which centuries later became the Great Mosque.</p>\n<p>In the 13th century, following the reconquest, the construction of the Cathedral was carried out gradually by making use of the Arab mosque, which is why the temple takes on a rounded shape rather than the traditional cross-shaped plan.</p>\n<p>Between 1229 and 1245, the Crown of Aragon conquered the territory that would later be known as the Kingdom of Valencia.</p>\n<p>Thanks to the troops of King James I, Valencia was reconquered in 1238.</p>\n<p>In his honour, years later, an ancient traditional Valencian ceramic painting was placed on the Cathedral wall.</p>\n<p>It represents the celebration of the mass held after the reconquest.</p>`,
"442": `<p>What sculpted figure can be seen in the frame of the painting?</p>\n<p>A dragon, a bat or perhaps a crown? Riddle me this!</p>`,
"443": `<p>Just one step to the right, a small chapel protected by railings opens up. This is the place where the first Mass was celebrated in Valencia after the city was conquered by King James I.</p>`,
"444": `<p>What can be seen inside?</p>\n<p>An altar, a flag — is there also a sword?</p>`,
"445": `<p>Above it is a commemorative plaque. In what year was this plaque displayed?</p>`,
"446": `<p>A few steps further on, to the right, another chapel closed with railings houses the statue of San Vicente Ferrer, Patron of Valencia.</p>`,
"447": `<p>In the building opposite the Cathedral, an imposing high-relief bronze door rises up, with small barred windows through which you can glimpse the interior of the <strong>Basílica de Valencia</strong>.</p>`,
"448": `<p>On 19 March, Father's Day in Spain and dedicated to Saint Joseph, the Fallas come to an end with the Nit de la Cremà (the Night of the Burning).</p>`,
"449": `<p>A night on which, from 10 pm, the children's monuments are burned until 1 am when the monument in the <strong>Plaza del Ayuntamiento</strong> is set alight — it is tradition to wander through Valencia bidding farewell to the Fallas, watching a whole year's work go up in flames.</p>\n<p>Continue towards the towers.</p>`,
"450": `<p>In 1652, construction of the basilica began and lasted a total of 14 years.</p>\n<p>Between 1652 and 1660, the exterior façades were built.</p>\n<p>In 1659, it was agreed to construct an elevated passage connecting the Basilica with the Cathedral, known as the "arco novo", and in early 1661 construction began on the oval-plan dome, nearly 19 metres wide.</p>\n<p>In 1666 the works were completed and that same year the Virgin was transferred from the Cathedral.</p>`,
"451": `<p>The <strong>Basílica de Valencia</strong> houses, within its walls, the image of our Patron, the Mother of all Valencians: the <strong>Virgen de los Desamparados</strong>, affectionately known in Valencia as la Xeperudeta, which means "little hunchback" in the Valencian language.</p>\n<p>The Virgin takes this name from her slight forward lean, which is interpreted as a sign of physical weariness from the effort and dedication of supporting the thousands of prayers offered by the Valencians.</p>\n<p>The prayers began as a consequence of the plague epidemic which in 1647 caused nearly 18,000 deaths. The increasingly fervent devotion of the Valencian people to the Virgin created the need to build a suitable space where her image could be displayed to the people under conditions befitting such devotion.</p>`,
"452": `<p>If you are visiting during opening hours, ${LOGO} advises pausing and visiting this historic monument at your own pace.</p>\n<p>You will be able to admire the frescoes by the famous painter Palomino, on display in this Basilica since 1701.</p>\n<p>You may also like to say a few words to the Virgin. Tradition holds that one should make a wish that is not for oneself.</p>\n<p>You may resume your adventure whenever you feel ready, simply press the corresponding button and continue <i>in search of the treasure</i>.</p>`,
"453": `<p>Bravo! You have almost completed your adventure!</p>\n<p>Look at your map carefully; the layout of the road obliges you to take a one-way route before turning right, thus obtaining a magnificent view of the <strong>Catedral de Valencia</strong>.</p>\n<p>On the way to the Romanesque Doorway, the Archbishop's Palace is on your left.</p>`,
"454": `<p>On the side opposite the Basilica, the ornamentation of a stately building reveals that it may be of importance in this treasure hunt.</p>`,
"455": `<p>Valencia is the Spanish city with the greatest volume of Modernist works, owing to the significant growth of the city at the end of the 19th century, which entailed the construction of the Ensanche and the demolition of the medieval walls in 1865.</p>\n<p>The emergence of Modernism was a movement breaking with the styles that had prevailed up to that point, with the intention of finding a more modern, youthful and functional style based on the use of new materials such as iron, glass and tiles, derived from industrial evolution.</p>\n<p>It was characterised by a certain exaltation of the vegetable garden, the falleras, oranges and fishermen, among other things.</p>\n<p>This is evident in works full of colourful mosaics, sculptures and floral decorations.</p>\n<p>The movement was driven by a new class: the bourgeoisie, who wished to assert themselves through art.</p>\n<p>They fled from tradition and robust construction, seeking movement... and the fundamental detail was ornamentation and nature.</p>\n<p>In Valencia, moreover, a current with its own distinctive characteristics developed, known as Valencian Modernism.</p>`,
"456": `<p>In what year was this building constructed?</p>\n<p>Hint! Look at the upper part of the façade.</p>`,
"457": `<p>An artificial elevation, to the left of this building, invites you to continue <i>in search of the treasure</i>.</p>\n<p>Let's go up!</p>\n<p>This is a perfect spot for panoramic photographs of these monuments declared of historic and artistic interest.</p>`,
"458": `<p>Nearby, a time portal has opened!</p>\n<p>What can be seen through it?</p>\n<p>A <strong>bullring</strong>, some Roman Baths or perhaps an Underground station?</p>`,
"459": `<p>Exactly! Some Roman baths — your mission? Find the massage table where treatments were given. It is true — it is still standing!</p>`,
"460": `<p>In the 13th century, after the Christian reconquest, the Almoina building was erected on this same structure, giving its name to the site.</p>\n<p>Almoina (which in Valencian means alms) was a medieval charitable institution that distributed food among the most disadvantaged.</p>`,
"461": `<p>As you can see, the architectural structure surrounding the square allows direct visual contact with the interior of the museum, while the outdoor spaces encourage dialogue in an environment where the vestiges of the past are the true protagonists.</p>\n<p>At this point stands one of the best archaeological centres in Europe, with ruins dating back to the founding of the city in 138 BC.</p>\n<p>This square is considered the oldest in the city. In the past, this very spot housed the Roman main square close to the forum — that is, the central area of the ancient city of Valentia.</p>\n<p>If you are visiting during opening hours, ${LOGO} recommends pausing and going inside this space to learn more about the history of the city.</p>\n<p>You may resume your adventure whenever you feel ready, simply press the corresponding button and continue <i>in search of the treasure</i>.</p>\n<p>Your adventure continues from this very point.</p>`,
"462": `<p>To this end, he granted ownership of all Muslim mosques and cemeteries to the archbishopric, which in turn Christianised these temples by renaming them as parishes dedicated to saints of the new religion that would be established in these lands.</p>\n<p>In 1245, the <strong>Iglesia de San Lorenzo</strong> was chosen as one of the ten founding parishes of the city.</p>\n<p>The temple we can see today dates from 1684, although the bell tower was built some years later, in 1747. Unfortunately, the earthquake of 1822 shifted it from its original axis — can you see it?</p>\n<p>The upper chamber houses two bells: Santa Anna, made in 1718, and Domingo, from 1742.</p>\n<p>The bell tower is crowned by a small cupola with a striking weather vane bearing the image of San Lorenzo.</p>`,
"463": `<p>Position yourself, if you would be so kind, in the centre of the square with the market directly in front of you. To the right of the famous <strong>Mercado Central</strong>, a magnificent Baroque church rises up — can you see it? On your map it corresponds to number <mark>16</mark>.</p>\n<p>Approach your next objective, San Juan del Mercado.</p>`,
"464": `<p>At the centre of the monument the Gothic <strong>Cimborrio</strong> stands out.</p>\n<p>Since the 15th century it has risen to a height of 40 metres, allowing natural light to flood in and illuminate the cathedral.</p>\n<p>Can you determine its shape? Hexagonal, Octagonal or Quadrangular?</p>`,
"465": `<p>Following the route on your map, turn around, leave the <strong>Basílica de la Virgen</strong> on your left and the <strong>Museo Arqueológico</strong> on your right, go to the end of the street and turn left.</p>\n<p>On the route, the <strong>Plaza de la Virgen</strong> comes into view.</p>`,
"466": `<p>The <strong>Plaza de la Virgen</strong> is surrounded by the Basilica, the Cathedral and the <strong>Barri de la Seu</strong> or <strong>Cathedral Quarter</strong>.</p>\n<p>In the northern half of the square, an attractive monumental bronze fountain draws the eye.</p>\n<p>Known as the Fuente de Neptuno, it is an allegorical representation of the <strong>River Turia</strong>.</p>`,
"467": `<p>Neptune holds a cornucopia of abundance in his hand and is surrounded by female figures wearing the headdresses of Valencian labourers, representing the main irrigation channels that water Valencia.</p>\n<p>In which hand does Neptune hold the cornucopia?</p>`,
"468": `<p>How many figures surround the fountain?</p>`,
"469": `<p>The square that opens before you is one of the most beloved settings for the people of Valencia, especially during our popular festivities, the Fallas.</p>`,
"470": `<p>Each year on 1 March, the city is bathed in the colours of flowers and gunpowder to welcome spring and more than a million visitors.</p>`,
"471": `<p>The Fallas are celebrated outdoors thanks to the fine weather that usually prevails, and because the city becomes pedestrianised.</p>\n<p>The packed streets, the contemplation of the Fallas monument and stops to refresh oneself are just some of the reasons why Valencia during the Fallas is an incomparable celebration.</p>`,
"472": `<p>During Fallas, everything is celebration: the roar of the mascletà, the casales, the street parades and the bands of music make their way through the more than 700 Fallas monuments.</p>\n<p>On 15 March, the Plantà or assembly of the monuments begins, some reaching 25 metres in height.</p>\n<p>The Fallas monuments, made from combustible materials such as wood, cardboard, paper and fabric, are burned after several days on display in the streets, a ritual that welcomes the arrival of spring.</p>`,
"473": `<p>Indeed, in the centre of this square, a wooden structure is erected each year to serve as a frame for weaving the multicoloured floral mantle of Valencia's Patron.</p>\n<p>The flower offering to the "Mare de Déu dels Desamparats" has its origins inside the Basilica, dating from 1941 when a group of market gardeners offered bunches of flowers to the Virgin.</p>`,
"474": `<p>But in just eight years, the Offering obliged the organisers to hold it outside the Basilica.</p>\n<p>Such was the devotion that frames were built on the façade of the temple to receive the bunches of flowers.</p>\n<p>In later years, children and marching bands were incorporated into the Offering processions.</p>\n<p>In time, it was agreed that only regional dress could be worn in the Offering, and new routes were organised; by 1964, the procession had tripled in size, gathering more than twenty thousand participants.</p>\n<p>Today, the Flower Offering runs from the 17th until the early hours of 19 March, with over one hundred and thirty thousand Falleras and Falleros leaving the <strong>Plaza de la Virgen</strong> filled with flowers.</p>`,
"475": `<p>Remember that, if you are visiting during opening hours, ${LOGO} recommends climbing this architectural treasure to learn more about the history of the city and its customs.</p>`,
"476": `<p>Direct your attention, from outside, slightly to the right of the basilica.</p>`,
"477": `<p>In the background, the Gothic Doorway of the Cathedral stands out — the second to be built.</p>\n \n<p>Known as the Puerta de los Apóstoles (Door of the Apostles) for the twelve figures sculpted on its façade, it was built in the 14th century and is formed by two superimposed sections.</p>\n<p>In the lower section, the doorway that projects from the wall can be distinguished, with pointed arches characteristic of the Gothic style and three archivolts with carved sculptures of angels and saints.</p>\n<p>In the tympanum of the door, a sculpture of Our Lady with the Child in her arms can be seen.</p>\n<p>On either side of the Virgin, angels playing musical instruments can be distinguished.</p>\n<p>Do not pause this audio guide and approach the portico, if you would be so kind.</p>`,
"478": `<p>In the upper section, the stone rose window stands out prominently, taking the form of the Seal of Solomon.</p>\n<p>With a diameter of six and a half metres, it serves to illuminate the cathedral.</p>\n<p>The rose window visible today is not the original from 1462, as it had to be replaced due to deterioration in 1957.</p>`,
"479": `<p>In its portico, every Thursday, the Water Tribunal is held — a swift oral hearing that resolves disputes arising from the use and management of irrigation water among farmers.</p>\n<p>The origin of this tribunal, though unknown, is believed to have had a precursor in Roman times, but its function as we know it today has existed for more than a millennium, dating from the Arab reign.</p>`,
"480": `<p>Following the course of the former river, some 200 metres away, is the esplanade from which the fireworks are launched. As you may have gathered, the people of Valencia have a great fondness for gunpowder.</p>`,
"481": `<p>The <strong>Palau de la Generalitat</strong> Valenciana is situated in the <strong>Barri de la Seu</strong> or <strong>Cathedral Quarter</strong> and began construction in 1421.</p>\n<p>With numerous restorations and extensions, in which the leading Valencian master craftsmen of their time participated, the former city hall is in the Valencian Gothic style with Renaissance additions.</p>`,
"482": `<p>The building was expanded in the 16th century with a second large tower of similar dimensions to the first.</p>\n<p>To build it, the stonemasons used black stone from Alcublas, white marble from the Valldigna and stone from Riba-roja — all localities close to Valencia.</p>`,
"483": `<p>Which of the two towers do you think is the newer one — the one facing the square, or the one directly in front of you now?</p>`,
"484": `<p>The answer? The one right in front of you!</p>`,
"485": `<p>Do not pause this audio guide. Stand with the monument we just mentioned on your left and continue, as indicated on your map, down the street opening to your right.</p>\n<p>On your map it corresponds to number <mark>45</mark>.</p>`,
"486": `<p>The well-known <strong>Calle Caballeros</strong> follows the east–west axis of the ancient Roman city, known at the time as the Decumanus Maximus.</p>\n<p>The Cathedral Monument Complex, the construction of the <strong>Palau de la Generalitat</strong> and the proximity of the Church of San Nicolás encouraged noble families to settle along this well-known street.</p>\n<p>Because of this, the historical and artistic value of <strong>Calle Caballeros</strong> is rooted in its being the focal point of the city's power.</p>\n<p>Within it, there are numerous small palaces where a large part of the Valencian nobility lived.</p>\n<p><strong>Calle Caballeros</strong> has kept its name since 1412.</p>\n<p>Keeping the same name for so long is quite an achievement for any city street.</p>`,
"487": `<p>Continue along <strong>Calle Caballeros</strong> to the next point of interest.</p>\n<p>On your map it corresponds to number <mark>46</mark>.</p>`,
"488": `<p>The <strong>Iglesia de San Nicolás</strong> is a few metres further ahead, on your left.</p>\n<p>Pay attention to the entrance, as it is disproportionately small for the size of the interior of the temple and could easily be overlooked.</p>`,
"489": `<p>The <strong>Iglesia de San Nicolás</strong> de Bari y San Pedro Mártir, also known as "the little Sistine Chapel of Valencia", is a Gothic-structure temple with Baroque interior decoration.</p>\n<p>Initially built in 1245 over an ancient Arab mosque, the church underwent a comprehensive renovation in 1455, giving it its current Gothic appearance.</p>\n<p>In 1693, the Gothic vault was covered with a Baroque one more in keeping with the era.</p>\n<p>Around the year 1700, an ambitious project began in its interior to cover more than 2,000 square metres with frescoes.</p>\n<p>The <strong>Iglesia de San Nicolás</strong> was declared a National Historic Artistic Monument in 1981, and today is one of the most visited churches in the city of Valencia.</p>`,
"490": `<p>If you are visiting during opening hours, ${LOGO} advises pausing and admiring the numerous and impressive details of the chapel's frescoes.</p>\n<p>When you decide to continue, look at your map, which takes you around the church to see its other façades, also worthy of mention.</p>\n<p>To do so, take the first street on your left.</p>`,
"491": `<p>With the door of San Nicolás on your left, make your way around the church and position yourself in the centre of the square, from where you can see a simple Gothic-style doorway.</p>`,
"492": `<p>The aim of this constant change is to be able to accommodate everyone, which is why different styles are displayed every fortnight and open dance classes are organised periodically.</p>`,
"493": `<p>The doorway was built in the 15th century, with archivolts resting on slender columns.</p>\n<p>Archivolts are decorative elements that resolve the aesthetic problem presented by openings or changes in level in a thick wall; they avoid the tunnel effect that can otherwise be created and allow more light into the interior.</p>\n<p>The Gothic style is characterised by pointed arches. This particular one is surmounted by an ogee arch.</p>\n<p>Imagine the arch divided into four segments; the result would be: two concave and two convex curves, which are characteristic of this type of arch.</p>\n<p>Just below the apex of this ogee arch, there is a curious relief. Focus your attention... Is it a representation of a platter... with... with meat on it?</p>\n<p>According to legend, while San Nicolás was travelling, he stopped at a tavern for dinner and the innkeeper served him a plate of meat.</p>\n<p>When he went to bless his meal, the Saint noticed that the meat was human.</p>\n<p>Nicolás reported the innkeeper, as the remains of three dismembered adolescents were also found in his cellar — the Saint miraculously reassembled and resurrected them.</p>`,
"494": `<p>Focus your attention on this ogee arch, beneath which a Gothic rose window from 1455 illuminates the church.</p>\n<p>This rose window, which takes the form of the Star of David or Seal of Solomon, is similar to the one you have already seen at the Cathedral.</p>`,
"495": `<p>To the right of the doorway, there is a chapel closed by railings.</p>\n<p>Inside, a ceramic panel depicting the "Cristo de Fossar" can be seen.</p>\n<p>It takes this name from the ancient cemetery that was located just beneath it.</p>`,
"496": `<p>What can be seen on this ceramic panel? Are there skulls? Is there a cross? Is there also a dove?</p>`,
"497": `<p>The bell tower, which is directly to the right, was completed in 1755 and restored in 2007.</p>\n<p>You can see that the tower is made up of three sections:</p>\n<p>The first, reaching the height of the rooftop.</p>\n<p>The second, built in brick, and the third, which houses the bells, visible through the semicircular arches.</p>`,
"498": `<p>How many bells does this tower house? 3, 4 or 5?</p>`,
"499": `<p>Your treasure map indicates continuing around the church to see the last of its doorways.</p>\n<p>A splendid neo-Gothic creation from 1864 bids farewell to this point and gives way to the next.</p>`,
"500": `<p>Continue to the end of the street, then turn left and follow the road until you see the next point of interest on your right — there, the <strong>Fuente del Negrito</strong> comes into view.</p>\n<p>On your map it corresponds to number <mark>48</mark>.</p>\n<p>Remember to press pause, then observe the indicated point, and press the continue button again once you are at the suggested location.</p>`
};

const merged = { ...existing, ...batch };
writeFileSync(FILE, JSON.stringify(merged, null, 2), 'utf8');
